 silver to monetary value: ~\\$1.292988/oz\n\n# For September of each year, market silver prices (in USD/oz):\n# According to historical records (measured in USD per troy ounce):\n# September 1938: ~\\$0.45 (the Silver Purchase Act ended in 1938, price fell)\n# September 1948: ~\\$0.71 (post-WWII period)\n# September 1958: ~\\$0.83-0.85 (before the big spike in 1960s)\n\n# Let me use these more accurate values:\nprice_1938 = 0.455  # 1938\nprice_1948 = 0.715  # 1948  \nprice_1958 = 0.835  # 1958\n\n# CPI values (from BLS, 1982-84=100):\n# 1938: 14.1, 1948: 24.1, 1958: 28.9\ncpi = {1938: 14.1, 1948: 24.1, 1958: 28.9}\n\n# Statutory rate\nrate = 1.292988\n\n# Nominal silver stock (millions USD)\nnominal = {1938: 3163.0, 1948: 3584.4, 1958: 4314.9}\n\n# Physical quantity in millions of troy ounces\noz = {y: nominal[y] / rate for y in [1938, 1948, 1958]}\n\nprint('Physical quantity (millions of oz):')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: {oz[y]:.2f}M oz')\n\n# Now we need real (inflation-adjusted) prices\n# Adjust all to 1938 dollars:\nbase_year = 1938\nreal_price = {}\nfor y in [1938, 1948, 1958]:\n    real_price[y] = price_(y) * (cpi[base_year] / cpi[y])\n    \nprint()\nprint('Real prices (1938 dollars):')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: \\${real_price[y]:.4f}/oz')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
