e[1948] = price_1948 * (cpi[base] / cpi[1948])\nreal_price[1958] = price_1958 * (cpi[base] / cpi[1958])\n\nprint()\nprint('Inflation-adjusted prices (1938 dollars):')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: \\${real_price[y]:.4f}/oz')\n\n# Compute values\ncomputed = {}\nfor y in [1938, 1948, 1958]:\n    computed[y] = oz[y] * real_price[y]\n\nprint()\nprint('Computed values (millions):')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: \\${computed[y]:.2f}M')\n\n# Median\nimport statistics\nmed = statistics.median(computed.values())\nprint(f'\\\\nMedian: \\${med:.2f}M')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
