\n# Let me check the exact rate from the bulletins\n# Gold is \\$35 per fine ounce - this is the official statutory rate\n# Silver is shown as '\\$1.29+' or '\\$1.29++' - this is the silver rate\n\n# The exact silver-to-dollar ratio from the Coinage Act of 1837:\n# 1 silver dollar = 371.25 grains of pure silver\n# 1 troy ounce = 480 grains\n# So: 480/371.25 = 1.292929... (or more precisely: 1.292988304)\n\n# Let me calculate using the exact value:\nrate_exact = 480.0 / 371.25\nprint(f'Exact rate: {rate_exact:.10f}')\n\n# Actually wait - maybe the problem expects \\$1.29 exactly (the rounded value from tables)\n# Let me try with \\$1.29\n\nrate_129 = 1.29\n\n# Silver stock values (millions)\nnominal = {1938: 3163.0, 1948: 3584.4, 1958: 4314.9}\n\n# Physical quantities using $1.29 rate\noz_129 = {y: nominal[y] / rate_129 for y in nominal}\n\n# Market silver prices (nominal)\nprice = {1938: 0.45, 1948: 0.71, 1958: 0.85}\n\n# Adjust to real prices using CPI (base year = 1938)\ncpi = {1938: 14.1, 1948: 24.2, 1958: 28.9}\n\nbase = 1938\nreal_price = {y: price[y] * (cpi[base] / cpi[y]) for y in [1938, 1948, 1958]}\n\n# Compute values\ncomputed = {y: oz_129[y] * real_price[y] for y in [1938, 1948, 1958]}\n\nprint('Using rate \\$1.29:')\nprint('Real prices (1938 \\$):')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: \\${real_price[y]:.4f}')\n    \nprint('Computed values:')\nfor y in [1938, 1948, 1958]:\n    print(f'  {y}: \\${computed[y]:.2f}M')\n\nimport statistics\nprint(f'Median: \\${statistics.median(computed.values()):.2f}M')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
